# Monitor CPU and memory
dotnet-counters monitor --process-id <pid>

# Collect CPU trace for 30 seconds
dotnet-trace collect --process-id <pid> --duration 00:00:30

# Collect memory dump
dotnet-dump collect --process-id <pid>

# Analyze dump
dotnet-dump analyze <dump-file>

# Visual Studio Diagnostic Tools
// - Performance Profiler (CPU Sampling, Memory Usage)
// - IntelliTrace (historical debugging)
// - Live Unit Testing

// Built-in endpoints for diagnostics
app.MapGet("/debug/endpoints", (EndpointDataSource eds) =>
{
    return eds.Endpoints.Select(e => new
    {
        RoutePattern = (e as RouteEndpoint)?.RoutePattern?.RawText,
        Methods = (e as HttpMethodMetadata)?.HttpMethods,
        DisplayName = e.DisplayName
    });
});
